import{_ as e,o,c as a,ae as i}from"./chunks/framework.CLL1HkDi.js";const u=JSON.parse('{"title":"Configuration and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/config.md","filePath":"guide/config.md"}'),d={name:"guide/config.md"};function r(s,t,n,l,c,h){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="configuration-and-permissions" tabindex="-1">Configuration and Permissions <a class="header-anchor" href="#configuration-and-permissions" aria-label="Permalink to &quot;Configuration and Permissions&quot;">​</a></h1><h2 id="configuration-config-json" tabindex="-1">Configuration (config.json) <a class="header-anchor" href="#configuration-config-json" aria-label="Permalink to &quot;Configuration (config.json)&quot;">​</a></h2><p>The <code>config.json</code> file is automatically generated in the <code>mods/Plots/</code> directory upon the first run.</p><h3 id="world-settings" tabindex="-1">World Settings <a class="header-anchor" href="#world-settings" aria-label="Permalink to &quot;World Settings&quot;">​</a></h3><ul><li><strong><code>PlotWorldName</code></strong>: The specific world where plot rules and generation apply.</li><li><strong><code>DefaultWorldTime</code></strong>: The standard time (in ticks) for the plot world (e.g., <code>6000</code> for noon).</li></ul><h3 id="plot-settings" tabindex="-1">Plot Settings <a class="header-anchor" href="#plot-settings" aria-label="Permalink to &quot;Plot Settings&quot;">​</a></h3><ul><li><strong><code>PlotSizeX</code>, <code>PlotSizeZ</code></strong>: The actual buildable area for each plot.</li><li><strong><code>RoadSizeX</code>, <code>RoadSizeZ</code></strong>: The width of the roads separating plots. Set to <code>0</code> if you want no roads (plots will be adjacent).</li></ul><h3 id="block-settings" tabindex="-1">Block Settings <a class="header-anchor" href="#block-settings" aria-label="Permalink to &quot;Block Settings&quot;">​</a></h3><p>Customizing these IDs allows you to change the look of the generated world without changing prefabs:</p><ul><li><strong><code>Bedrock</code></strong>: The bottom layer.</li><li><strong><code>PlotSurface</code></strong>: The top layer of the builder&#39;s area.</li><li><strong><code>PlotSubSurface</code></strong>: The material directly under the surface.</li><li><strong><code>RoadSurface</code></strong>: The material used for roads.</li><li><strong><code>Border</code></strong>: The block used for the plot perimeter.</li><li><strong><code>Filling</code></strong>: The mass material from Y=1 to Y=60.</li></ul><h3 id="spawn-settings" tabindex="-1">Spawn Settings <a class="header-anchor" href="#spawn-settings" aria-label="Permalink to &quot;Spawn Settings&quot;">​</a></h3><ul><li><strong><code>X</code>, <code>Y</code>, <code>Z</code>, <code>Pitch</code>, <code>Yaw</code></strong>: Use the <code>/plot setspawn</code> command to update these easily.</li><li><strong><code>CustomSpawn</code></strong>: If <code>true</code>, the plugin will always use these coordinates for the world spawn instead of generating one.</li></ul><hr><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>plots.claim</code></td><td>Permission to claim plots.</td><td>Player</td></tr><tr><td><code>plots.auto</code></td><td>Permission to use <code>/plot auto</code>.</td><td>Player</td></tr><tr><td><code>plots.info</code></td><td>Permission to view plot metadata.</td><td>Player</td></tr><tr><td><code>plots.spawn</code></td><td>Permission to teleport to world spawn.</td><td>Player</td></tr><tr><td><code>plots.use</code></td><td>Access to basic plot management (trust, rename).</td><td>Player</td></tr><tr><td><code>plots.admin</code></td><td>Full access and protection bypass.</td><td>OP / Admin</td></tr></tbody></table>',15)])])}const p=e(d,[["render",r]]);export{u as __pageData,p as default};
